  appOnlyOfferThisOffer: "অ্যাপ-অনলি অফার: এই অফারটি শুধু দোকানের ইনস্টল করা অ্যাপে (standalone মোডে) দেখানো হবে। তবে কোডটি শেয়ার হলে ওয়েবেও কাজ করবে — এটি শুধু প্রদর্শনের নিয়ম, কোড বন্ধ করার ব্যবস্থা নয়।",
