  accountsByBookingDateDefault: "বুকিংয়ের তারিখ অনুযায়ী হিসাব (ডিফল্ট: শেষ ৩০ দিন)। RTO হার = ফেরত ÷ বুকিং। গড় ফেরত-সময় শুধু সেই পার্সেলগুলো থেকে হিসাব হয় যাদের বুকিং ও ফেরত — দুটো ঘটনাই GC14 ইভেন্ট লগে আছে (n দেখানো হয়েছে); আগের পার্সেলের সময় আন্দাজ করা হয় না। যেসব ফেরত পার্সেলের কাজ বাকি, সেগুলো Orders পেজের &quot;RTO — ফেরত পার্সেল দেখা বাকি&quot; কিউতে পাবেন।",
