  forSecurityTheFullCode: "নিরাপত্তার জন্য পূর্ণ কোড এখানে কখনো দেখানো হয় না — কোড শুধু প্রাপকের ইমেইল/ফোনে যায়। তাই প্রাপকের ইমেইল বা ফোন যেকোনো একটি দেওয়া বাধ্যতামূলক।",
