  ifFilledAFloatingWhatsApp: "ভর্তি থাকলে দোকানে ভাসমান WhatsApp / Messenger বোতাম দেখাবে — ক্রেতা এক ক্লিকে চ্যাট শুরু করতে পারবে। খালি রাখলে সেই বোতামটি দেখাবে না।",
  putYourOwnGoogleAccount: "আপনার নিজের Google অ্যাকাউন্টের আইডি বসান — ভর্তি থাকলেই দোকানে সেই ট্যাগ চলবে, খালি রাখলে কোনো ট্যাগ যাবে না।",
  ifYouRunGA4Via: "⚠️ GTM দিয়ে GA4 চালালে এখানে আবার বসাবেন না — দ্বিগুণ গণনা হতে পারে।",
  putYourMetaPixelID: "আপনার Meta Pixel ID বসান। একাধিক অ্যাকাউন্ট বা পিক্সেল থাকলে কমা (,) দিয়ে লিখুন — সবগুলোতেই স্বয়ংক্রিয়ভাবে PageView, ViewContent, AddToCart, InitiateCheckout ও Purchase যাবে।",
  pixelIDObtainedFromTikTok: "TikTok Ads Manager থেকে প্রাপ্ত Pixel ID। একাধিক থাকলে কমা (,) দিয়ে লিখুন।",
