  onlyTheContentTokenOf: "Google Search Console এর HTML tag ভেরিফিকেশন মেটা ট্যাগের শুধু content টোকেনটি।",
  useAtYourOwnResponsibility: "⚠️ নিজের দায়িত্বে ব্যবহার করুন — ভুল কোড দোকানের পেজ ভেঙে দিতে পারে। কাস্টম JS শুধু দোকানের নিজের হোস্টে চলে (মূল অ্যাপের হোস্টে নয়)।",
  theServerDoesNotAccept: "বন্ধ করার ট্যাগ (&lt;/style&gt;, &lt;/script&gt;) সার্ভার গ্রহণ করে না — এমন কোড দিলে সংরক্ষণ ব্যর্থ হবে এবং সার্ভারের বার্তাটি ওপরে দেখানো হবে। CSS শুধু দোকানের পেজে প্রযোজ্য; JS চালু করতে নিচের টগলটি অন করতে হবে, নাহলে JS সংরক্ষিত থাকলেও চলবে না।",
