  arrangePagesLikeReturnPolicy: "রিটার্ন নীতি, শর্তাবলি, আমাদের সম্পর্কে ইত্যাদি পেজ ব্লক দিয়ে সাজান। প্রকাশিত পেজ পাবলিক লিংকে দেখা যাবে; ফুটার/মেনুতে দেখানোর অপশনও এখান থেকেই।",
  selectAPageFromThe: "বামে তালিকা থেকে একটি পেজ বেছে নিন, অথবা &ldquo;+ নতুন পেজ&rdquo; দিয়ে নতুন পেজ শুরু করুন।",
  theShopSSearchIs: "দোকানের সার্চ কীওয়ার্ড / পূর্ণ-টেক্সট অনুসন্ধান (FTS) ভিত্তিক — এখানে &ldquo;স্মার্ট সার্চ&rdquo; বলতে পূর্ণ-টেক্সট অনুসন্ধানই বোঝানো হয়েছে। ক্রেতারা কী খুঁজছেন এবং কোন খোঁজে কোনো ফল আসছে না, তা এখানে দেখুন।",
