  staffCreateWhenTheTime: "স্টাফ তৈরি করে — সময় হলে sweep একটি COD নবায়ন অর্ডার তৈরি করে (স্বয়ংক্রিয় পেমেন্ট চার্জ নেই)।",
  theCustomerHasConsentedTo2: "গ্রাহক ভবিষ্যৎ অটো-চার্জে সম্মতি দিয়েছেন — সম্মতিটি রেকর্ড করুন",
  evenIfConsentIsRecorded: "⚠️ সম্মতি রেকর্ড হলেও চার্জিং এখনো চালু নয় — টোকেনাইজড অটো-চার্জ চালু না হওয়া পর্যন্ত প্রতিটি নবায়ন আগের মতোই COD অর্ডার হবে, কোনো টাকা স্বয়ংক্রিয়ভাবে কাটা হবে না।",
  conflictResolvedThePerField: "Conflict নিষ্পত্তি হয়েছে — ফিল্ড অনুযায়ী বেছে নেওয়া মানগুলো প্রয়োগ হয়েছে।",
  everyChangeSentToThe: "এখান থেকে স্টোরে পাঠানো প্রতিটি পরিবর্তন প্রথমে Outbox এ জমা হয়, তারপর প্ল্যাটফর্মে যায়। কোনো আইটেম ব্যর্থ হলে প্ল্যাটফর্মের দেওয়া আসল (verbatim) এরর এখানেই দেখানো হয়। প্ল্যাটফর্ম যে অপারেশন সমর্থন করে না, তা সফল বলে দেখানো হয় না — সেটি failed হিসেবেই চিহ্নিত থাকে।",
  theStoreSRealUnit: "স্টোরের আসল একক Health Check-এ Woo Settings থেকে পড়ে সংরক্ষণ করা হয়; এখান থেকে হাতে বদলানো যায়। পণ্যের ওজন গ্রামে সংরক্ষিত থাকে, পাঠানোর সময় এই এককে রূপান্তর হয়।",
