  ifOffTheStoreCredit: "বন্ধ থাকলে অর্ডারের Refund অংশে স্টোর ক্রেডিটের অপশনই দেখা যাবে না এবং API-ও ক্রেডিটে রিফান্ড নেবে না। চালু থাকলে refund কাস্টমারের স্টোর ক্রেডিট লেজারে জমা হবে। শুধু OWNER বদলাতে পারেন।",
