  ordersFromTheseDistrictsWill: "এই জেলাগুলোর অর্ডার প্রথমে এই গুদাম থেকে বরাদ্দ পাবে। ভুল নাম দিলে সার্ভারের বার্তা দেখানো হবে।",
  allocatingTheSameProductAgain: "একই পণ্য আবার বরাদ্দ করলে সেটি আগের বিন থেকে নতুন বিনে সরে যায় (MOVE)।",
  noBalancesYetBalancesWill: "এখনো কোনো ব্যালেন্স নেই। স্টক নড়াচড়া হলেই (অর্ডার, সমন্বয়, স্থানান্তর) এখানে ব্যালেন্স দেখা যাবে; AB3-র আগের স্টক ডিফল্ট বিনে দেখানো হয়।",
  notDistributedMeansThisStock: "“বণ্টন হয়নি” মানে এই স্টক এখনো কোনো বিনে ভাগ হয়নি — মোট হিসাব থেকে দেখানো হচ্ছে; প্রথম স্টক-নড়াচড়াতেই এটি ডিফল্ট বিনে বসে যাবে।",
  noStockMovesInA: "খসড়ায় কোনো স্টক সরে না — “প্রেরণ করুন” চাপলেই উৎস বিন থেকে স্টক পথে বেরোয়।",
  ifTheFieldIsLeft: "ঘর খালি রাখলে/না বদলালে পুরো পাঠানো পরিমাণই গ্রহণ ধরা হবে। কম পেলে পার্থক্য রেকর্ড হবে — স্টক ফেরত যাবে না।",
